#{id}
order by marketing_spu_id asc, marketing_sku_id asc, rental_method asc, rental_period_month asc, id asc

select * from marketing_product_sku_rental_method_property where is_deleted = 0 and marketing_sku_id in
#{id}
order by marketing_sku_id asc, rental_method asc, rental_period_month asc, id asc

select *
from marketing_product_sku_rental_method_property
where is_deleted = 0
  and marketing_sku_id = #{marketingSkuId}
  and rental_method = #{rentalMethod}
  and rental_period_month = #{rentalPeriodMonth}
limit 1

mapper.update:
update marketing_product_sku_rental_method_property
set stock = stock - #{quantity},
    update_time = #{updateTime}
where is_deleted = 0
  and marketing_sku_id = #{marketingSkuId}
  and rental_method = #{rentalMethod}
  and rental_period_month = #{rentalPeriodMonth}
  and stock >= #{quantity}

update marketing_product_sku_rental_method_property
set stock = stock + #{quantity},
    update_time = #{updateTime}
where is_deleted = 0
  and marketing_sku_id = #{marketingSkuId}
  and rental_method = #{rentalMethod}
  and rental_period_month = #{rentalPeriodMonth}

update marketing_product_sku_rental_method_property
set is_deleted = id,
    update_by = #{updateBy},
    update_time = #{updateTime}
where marketing_spu_id = #{marketingSpuId}
  and is_deleted = 0
